  <dialog id="photo-modal"><form method="dialog"><button class="icon-button" aria-label="关闭图片">${ph(`close`)}</button></form><img id="modal-img" alt="现场参考"/><div><h2 id="modal-title"></h2><p id="modal-note"></p><button id="match-photo" class="secondary-button">按此照片方向观察模型</button></div></dialog>
